mapper.select:


    inner join sys_user u on u.user_name = tcontactsunit.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tcontactsunit.del_flag = '0'
     and tcontactsunit.name like concat('%', #{name}, '%')
     and tcontactsunit.type = #{type}
     and tcontactsunit.address like concat('%', #{address}, '%')
     and tcontactsunit.phone = #{phone}


${params.dataScope}
order by tcontactsunit.create_time desc
